from typing import List, Optional

def max_sub_array_sum(nums: List[int]) -> Optional[int]:
    if not nums:
        return None
    max_ending_here = max_so_far = nums[0]
    for num in nums[1:]:
        max_ending_here = max(num, max_ending_here + num)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

