def next_smallest_palindrome(num: int) -> int:
    s = str(num + 1)
    length = len(s)

    def is_all_nines(n):
        return all(ch == '9' for ch in n)

    # If all digits are 9, the next palindrome is 10..01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        length = len(s)
        half = length // 2
        if length % 2 == 0:
            left = s[:half]
            middle = ''
            right = s[half:]
            palindrome = left + left[::-1]
        else:
            left = s[:half]
            middle = s[half]
            right = s[half + 1:]
            palindrome = left + middle + left[::-1]

        if palindrome >= s:
            return int(palindrome)

        # Increment the middle part and rebuild palindrome
        if length % 2 == 0:
            # Even length: increment left half and mirror
            incremented = str(int(left) + 1)
            if len(incremented) > len(left):  # overflow, e.g. 99 + 1 -> 100
                s = '1' + ('0' * (length - 1)) + '1'
            else:
                s = incremented + incremented[::-1]
        else:
            # Odd length: increment left+middle and mirror
            left_middle = left + middle
            incremented = str(int(left_middle) + 1)
            if len(incremented) > len(left_middle):  # overflow
                s = '1' + ('0' * (length - 1)) + '1'
            else:
                left = incremented[:-1]
                middle = incremented[-1]
                s = left + middle + left[::-1]

