from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    # If the string contains spaces, split into groups
    groups = paren_string.split() if ' ' in paren_string else [paren_string]

    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

def smallest_change(nums):
    n = len(nums)
    changed_indices = set()
    for i in range(n // 2):
        if nums[i] != nums[n - 1 - i]:
            changed_indices.add(i)
            changed_indices.add(n - 1 - i)
    return len(changed_indices)

