    return bin(c)[2:].rjust(2, '0')

def digits(val):
    odd_digits = [int(d) for d in str(val) if int(d) % 2 == 1]
    if not odd_digits:
        return 0
    product = 1
    for d in odd_digits:
        product *= d
    return product

